const isStale = Date.now() - fetchedAt > 30_000;   // shown in the UI, not hidden`,failureModeOrInvariant:"A user opening the dashboard offline sees yesterday’s numbers clearly labelled as stale, rather than either a spinner forever or stale numbers presented as current.",architecturalLesson:"Showing cached data is a product decision as much as a technical one. The honest version tells the user how old the number is."}],layers:[{layer:"Design",components:["component tree diagram","state inventory","failure table","cache policy table"],invariants:["No component is written before its row exists in the state inventory."]},{layer:"Data",components:["query cache","IndexedDB persister","retry with backoff"],invariants:["Server state never lives in the client store, and vice versa."]},{layer:"View",components:["per-widget error boundary","skeletons","stale badge","offline banner"],invariants:["A single widget failure never blanks the page."]}],explicitTopics:[{category:"Architecture",topic:"System design",subtopic:"Components, data, states, failure",howCovered:"The design document is the first deliverable and the build is graded against it.",conceptIds:["frontend-system-design"]},{category:"Web Platform",topic:"Storage",subtopic:"Cookies, localStorage, sessionStorage, IndexedDB",howCovered:"Cached responses are persisted to IndexedDB, with an argued reason for not using localStorage.",conceptIds:["web-storage"]},{category:"Web Platform",topic:"Network",subtopic:"Status codes, idempotency and retry policy",howCovered:"The retry policy distinguishes idempotent from non-idempotent requests and 4xx from 5xx.",conceptIds:["web-http"]},{category:"State Management",topic:"Choosing",subtopic:"Context, Zustand, TanStack Query — the right tool",howCovered:"Server and client state are deliberately given different tools, with the split written down.",conceptIds:["state-alternatives"]},{category:"React Advanced",topic:"Escape hatches",subtopic:"Error boundaries and Suspense",howCovered