// CSS: .inspector-subgrid { display: grid; grid-template-columns: subgrid; }`,failureModeOrInvariant:"Zero layout shift across nested property inputs. Screen readers navigate hidden AOM mirror with full ARIA semantics.",architecturalLesson:"True masterclass engineering combines raw performance with polished UI design systems and WCAG accessibility."}],layers:[{layer:"Presentation",components:["React 19 Shell","OffscreenCanvas WebGL Viewport","Multiplayer Cursor LERP","Subgrid Token Panel"],invariants:["Zero main-thread vector drawing; UI renders only chrome and tools."]},{layer:"Application",components:["BVH Spatial Index","CRDT Sync Coordinator","CQRS Undo/Redo Engine","A11y Virtual Mirror"],invariants:["O(log N) frustum culling before dispatching draw calls."]},{layer:"Domain",components:["VectorShape Entity","Transform Mat3x3 Value Object","State Vector Clock"],invariants:["Commutative CRDT merges guarantee identical state across peers."]},{layer:"Infrastructure",components:["WebSocket Binary Protobuf","Comlink Worker Pool","Float32 Memory Pools"],invariants:["Zero heap allocations during steady-state 120 FPS loops."]}],explicitTopics:[{category:"React 19",topic:"useOptimistic",subtopic:"Real-Time Shape Transforms",howCovered:"Instantly applies shape transforms and layer orders before peer confirmation.",conceptIds:["r19-actions","react-state"]},{category:"Performance",topic:"INP & Long Tasks",subtopic:"OffscreenCanvas Offloading",howCovered:"Offloads all vector math and draw calls to Web Workers via OffscreenCanvas.",conceptIds:["react-perf","web-how-page-loads"]},{category:"Web Platform",topic:"Web Workers",subtopic:"Zero-Copy Transferables",howCovered:"Transfers ArrayBuffers without cloning between UI and render workers.",conceptIds:["react-references-copying","js-event-loop"]},{category:"CSS",topic:"Modern CSS",subtopic:"Subgrid & Container Queries",howCovered:"Property inspector aligned via CSS Subgrid with @container adaptive cards.",conceptIds:["css-token