// href/src are validated against an allowlist: javascript: is a script tag`,failureModeOrInvariant:"A plugin returning a node with an onClick string, a javascript: href, or an unknown type is rejected at the schema rather than rendered. A plugin missing its 32ms frame budget is terminated and shown as degraded, not allowed to drop frames for everyone.",architecturalLesson:"Untrusted UI is data describing a tree, never markup. The host decides what a described node is permitted to become."}],layers:[{layer:"Host",components:["capability registry","RPC router","watchdog","plugin surface renderer"],invariants:["No host object reference ever crosses the postMessage boundary."]},{layer:"Boundary",components:["null-origin iframe","per-plugin Worker","structured-clone transport","CSP"],invariants:["allow-scripts and allow-same-origin are never set together."]},{layer:"Plugin",components:["plugin SDK shim","declared capability manifest"],invariants:["A plugin holds only capabilities its manifest declared and the user approved."]}],explicitTopics:[{category:"Web Platform",topic:"Security",subtopic:"XSS, CSRF, clickjacking and CSP",howCovered:"The threat model is written first; CSP, sandbox flags and URL-scheme validation are each defeated then fixed.",conceptIds:["web-security"]},{category:"Web Platform",topic:"Network",subtopic:"Same-origin policy, origins and CORS",howCovered:"The null-origin iframe makes the same-origin policy the enforcement mechanism rather than a footnote.",conceptIds:["web-cors"]},{category:"Web Platform",topic:"Storage",subtopic:"Origin-partitioned storage",howCovered:"Demonstrates that a null-origin frame shares no cookies, localStorage or IndexedDB with the host.",conceptIds:["web-storage"]},{category:"JavaScript",topic:"Data",subtopic:"Structured clone vs references",howCovered:"structuredClone is used as the only transport precisely because it cannot carry a function.",conceptIds:["react-references-copying","js-arrays-objects"]},{category:"TypeS